/**
 * api 域实现：端点处理器（只做 HTTP 形状与参数搬运，判定全在注入端口里）。
 *
 * - PUT /config：体上限 64KB；校验失败 400（仅类别+码）；成功回裸 v1 掩码体；
 * - GET /presets 只读（PUT 进方法表即 405，不在此分流）；
 * - GET /history：root 兼容完整路径/rootHash；单测锁定 limit 钳制语义由 history 域承载；
 * - DELETE /history：root 与 sessionId 双必填（缺一 400，仅单会话）；
 * - POST /test-connection：空体 {} 合法（密钥取自服务端配置，不取自请求体）。
 */
import type { IncomingMessage } from "node:http";
import { ROUTES, TEMPLATE_VERSION } from "../../../shared/interface.ts";
import type { ApiDeps } from "../deps.ts";
import type { Endpoint } from "./route.ts";
import { sendFailure, sendJson } from "./route.ts";

/** 请求体上限（64KB；超限 413 不读完）。 */
const MAX_BODY_BYTES = 64 * 1024;

/** 读 JSON 体（空体即 {}；超限/非法抛错由调用方收口 400/413）。 */
function readJsonBody(req: IncomingMessage): Promise<unknown> {
  return new Promise<unknown>((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on("data", (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        reject(new Error("body too large"));
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => {
      const text = Buffer.concat(chunks).toString("utf8").trim();
      if (text.length === 0) {
        resolve({});
        return;
      }
      try {
        resolve(JSON.parse(text) as unknown);
      } catch {
        reject(new Error("body not JSON"));
      }
    });
    req.on("error", (cause: unknown) =>
      reject(cause instanceof Error ? cause : new Error(String(cause))),
    );
  });
}

/** 查询参数（相对 URL 用占位基拼）。 */
function queryOf(req: IncomingMessage): URLSearchParams {
  const raw = req.url ?? "/";
  return new URL(raw, "http://127.0.0.1").searchParams;
}

/** 数值参数（非法即 undefined，由域层回落默认）。 */
function numParam(params: URLSearchParams, key: string): number | undefined {
  const raw = params.get(key);
  if (raw === null || raw === "") return undefined;
  const num = Number(raw);
  return Number.isFinite(num) ? num : undefined;
}

/** 组装端点表（处理器全部经 ports 注入能力）。 */
export function buildEndpoints(ports: ApiDeps): Endpoint[] {
  return [
    {
      path: ROUTES.health,
      methods: {
        GET: (_req, res) => {
          sendJson(res, 200, {
            ok: true,
            version: ports.version(),
            templateVersion: TEMPLATE_VERSION,
          });
        },
      },
    },
    {
      path: ROUTES.config,
      methods: {
        GET: (_req, res) => {
          sendJson(res, 200, ports.readConfig());
        },
        PUT: (req, res) => {
          readJsonBody(req)
            .then(
              (body) => {
                try {
                  sendJson(res, 200, ports.writeConfig(body));
                } catch (cause: unknown) {
                  const failure = asFailure(cause);
                  sendFailure(
                    res,
                    failure.status,
                    failure.errorCode,
                    failure.category,
                    failure.message,
                  );
                }
              },
              () =>
                sendFailure(res, 400, "INVALID_BODY", "bad-request", "body must be JSON <=64KB"),
            )
            .catch(() => sendFailure(res, 500, "INTERNAL", "internal", "unreachable"));
        },
      },
    },
    {
      path: ROUTES.presets,
      methods: {
        GET: (_req, res) => {
          sendJson(res, 200, { ok: true, presets: ports.readPresets() });
        },
      },
    },
    {
      path: ROUTES.history,
      methods: {
        GET: (req, res) => {
          try {
            const params = queryOf(req);
            const entries = ports.readHistory({
              root: params.get("root") ?? undefined,
              sessionId: params.get("sessionId") ?? undefined,
              limit: numParam(params, "limit"),
            });
            sendJson(res, 200, { ok: true, entries });
          } catch (cause: unknown) {
            const failure = asFailure(cause);
            sendFailure(res, failure.status, failure.errorCode, failure.category, failure.message);
          }
        },
        DELETE: (req, res) => {
          try {
            const params = queryOf(req);
            const removed = ports.removeHistory({
              root: params.get("root") ?? undefined,
              sessionId: params.get("sessionId") ?? undefined,
            });
            sendJson(res, 200, { ok: true, deleted: removed.deleted });
          } catch (cause: unknown) {
            const failure = asFailure(cause);
            sendFailure(res, failure.status, failure.errorCode, failure.category, failure.message);
          }
        },
      },
    },
    {
      path: ROUTES.testConnection,
      methods: {
        POST: (req, res) => {
          readJsonBody(req)
            .then(
              (body) => {
                ports
                  .probeConnection(body)
                  .then(
                    (probe) => {
                      if (probe.ok) sendJson(res, 200, { ok: true, latencyMs: probe.latencyMs });
                      else
                        sendFailure(
                          res,
                          probeStatus(probe.errorCode),
                          probe.errorCode,
                          probe.category,
                          probe.message,
                        );
                    },
                    (cause: unknown) => {
                      const failure = asFailure(cause);
                      sendFailure(
                        res,
                        failure.status,
                        failure.errorCode,
                        failure.category,
                        failure.message,
                      );
                    },
                  )
                  .catch(() => sendFailure(res, 500, "INTERNAL", "internal", "unreachable"));
              },
              () =>
                sendFailure(res, 400, "INVALID_BODY", "bad-request", "body must be JSON <=64KB"),
            )
            .catch(() => sendFailure(res, 500, "INTERNAL", "internal", "unreachable"));
        },
      },
    },
  ];
}

/** 结构化抛错信封（组合根 writeConfig 按此 JSON 抛错，免跨域值引用）。 */
export interface ThrownFailure {
  readonly status: number;
  readonly errorCode: string;
  readonly category: string;
  readonly message: string;
}

/** 域抛错映射（JSON 信封优先；history[400] 前缀回落 400；余者 500）。 */
function asFailure(cause: unknown): {
  readonly status: number;
  readonly errorCode: string;
  readonly category: string;
  readonly message: string;
} {
  const message = cause instanceof Error ? cause.message : String(cause);
  try {
    const parsed = JSON.parse(message) as Partial<ThrownFailure>;
    if (
      typeof parsed.status === "number" &&
      typeof parsed.errorCode === "string" &&
      typeof parsed.category === "string" &&
      typeof parsed.message === "string"
    ) {
      return {
        status: parsed.status,
        errorCode: parsed.errorCode,
        category: parsed.category,
        message: parsed.message,
      };
    }
  } catch {
    // 非信封按前缀规则回落。
  }
  const match = /\[(\d+)\]/.exec(message);
  if (match !== null) {
    const status = Number(match[1]);
    return {
      status,
      errorCode: "BAD_REQUEST",
      category: "bad-request",
      message: message.replace(match[0], "").trim(),
    };
  }
  return { status: 500, errorCode: "INTERNAL", category: "internal", message };
}

/** 探针错误码映射状态（凭据/缺 key 401 形，余者 502）。 */
function probeStatus(errorCode: string): number {
  if (errorCode === "NO_KEY" || errorCode === "UNAUTHORIZED") return 401;
  if (errorCode === "TIMEOUT") return 504;
  return 502;
}

/**
 * api 域实现：路由围栏（回环 403 先于方法 405，异常收口 500）。
 *
 * - 非回环一律 403（默认参数，不放行 cross-site：普通 /api 路由）；
 * - 方法不在表里给 405（Allow 头带合法方法），不给 404；
 * - 处理器抛错收口 500（已发头则不再写头）。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import { isLoopbackRequest } from "../../../../../../shared/loopback.js";
import type { LoggerPort } from "../deps.ts";

/** 端点方法表（键为大写方法名）。 */
export type MethodTable = Record<
  string,
  (req: IncomingMessage, res: ServerResponse) => void | Promise<void>
>;

/** 端点（path 精确匹配）。 */
export interface Endpoint {
  readonly path: string;
  readonly methods: MethodTable;
}

/** 注册口（组合根转交的 ctx.webServer.register 窄面）。 */
export type RegisterRoute = (route: {
  readonly kind: "exact";
  readonly path: string;
  readonly handler: (req: IncomingMessage, res: ServerResponse) => void;
}) => () => void;

/** JSON 成功体。 */
export function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "cache-control": "no-store",
  });
  res.end(JSON.stringify(body));
}

/** 失败包络（必含 errorCode + category，供客户端 failureCategory 识别）。 */
export function sendFailure(
  res: ServerResponse,
  status: number,
  errorCode: string,
  category: string,
  message: string,
): void {
  sendJson(res, status, { ok: false, error: { errorCode, category, message } });
}

/** 注册端点组（返回摘除器；与装配顺序逆序释放由调用方组织）。 */
export function registerEndpoints(
  register: RegisterRoute,
  endpoints: Endpoint[],
  logger: LoggerPort,
): (() => void)[] {
  const disposers: (() => void)[] = [];
  for (const endpoint of endpoints) {
    disposers.push(
      register({
        kind: "exact",
        path: endpoint.path,
        handler: (req, res) => {
          if (!isLoopbackRequest(req)) {
            // R3：围栏体与失败体统一为 errorCode+category（客户端 failureCategory 读四键容忍，旧三键不再产出）。
            sendFailure(
              res,
              403,
              "FORBIDDEN_LOOPBACK",
              "loopback-only",
              "forbidden: loopback-only",
            );
            return;
          }
          const handle = endpoint.methods[req.method ?? ""];
          if (handle === undefined) {
            res.writeHead(405, {
              "content-type": "application/json; charset=utf-8",
              allow: Object.keys(endpoint.methods).join(", "),
            });
            res.end(
              JSON.stringify({
                ok: false,
                error: {
                  errorCode: "METHOD_NOT_ALLOWED",
                  category: "method-not-allowed",
                  message: "method not allowed",
                },
              }),
            );
            return;
          }
          try {
            const done = handle(req, res);
            if (done instanceof Promise) {
              done.catch((cause: unknown) => reportFailure(res, logger, cause));
            }
          } catch (cause: unknown) {
            reportFailure(res, logger, cause);
          }
        },
      }),
    );
  }
  return disposers;
}

/** 异常收口（记日志 + 500；已发头不再写）。 */
function reportFailure(res: ServerResponse, logger: LoggerPort, cause: unknown): void {
  const reason = cause instanceof Error ? cause.message : String(cause);
  logger.warn("dsh-decision-gateway: 端点处理失败 —— " + reason);
  if (!res.headersSent) sendFailure(res, 500, "INTERNAL", "internal", reason);
}

/** api 域实现：装配（端点表 + 围栏注册；无状态，释放器由调用方持有）。 */
import type { ApiDeps } from "../deps.ts";
import { buildEndpoints } from "./handlers.ts";
import type { RegisterRoute } from "./route.ts";
import { registerEndpoints } from "./route.ts";

/** 装配浏览器出口（组合根在 apply 期调用一次；返回摘除器）。 */
export function installApi(deps: ApiDeps): (() => void)[] {
  return registerEndpoints(
    deps.register as unknown as RegisterRoute,
    buildEndpoints(deps),
    deps.logger,
  );
}

